  _featuredArea(areas=(this._boot?.areas||[]).filter(a=>!this._boot?.config?.hidden_areas?.includes(a.id))){const configured=areas.find(a=>a.id===this._boot?.config?.featured_area_id);return configured||[...areas].sort((a,b)=>Number(Boolean(this._ownBackground(b)))-Number(Boolean(this._ownBackground(a)))||this._areaEntities(b.id).length-this._areaEntities(a.id).length||this._areaName(a).localeCompare(this._areaName(b),this._lang()))[0]}
  async _resolveConfiguredMedia(){this._resolvedBackgrounds={};const entries=Object.entries(this._boot?.config?.media_backgrounds||{});await Promise.all(entries.map(async([areaId,mediaId])=>{try{const result=await this._hass.callWS({type:"media_source/resolve_media",media_content_id:mediaId,expires:604800});if(result?.mime_type?.startsWith("image/")&&result.url)this._resolvedBackgrounds[areaId]=result.url}catch(err){console.warn("SmplWise media background could not be resolved",areaId,err)}}))}
  _summary(entities){ const counts={}; for(const s of entities){const d=domainOf(s.entity_id);counts[d]=(counts[d]||0)+(isOn(s.state)?1:0);} return counts; }

